// Fictional AI-invoice records. The large IDs are intentionally numeric JSON tokens.
// No external data, API requests or credentials.
const approvedNumericJSON = '{"invoice_id":9007199254740992,"amount":"149.00"}';
const aiNumericJSON = '{"invoice_id":9007199254740993,"amount":"149.00"}';
// A separate lossless representation, captured BEFORE lossy number parsing.
const approvedStringJSON = '{"invoice_id":"9007199254740992","amount":"149.00"}';
const aiStringJSON = '{"invoice_id":"9007199254740993","amount":"149.00"}';
return [{json:{approvedNumericJSON,aiNumericJSON,approvedStringJSON,aiStringJSON,case:'SYNTHETIC_INVOICE_ID'}}];

const input = $input.first().json;
const a = JSON.parse(input.approvedNumericJSON);
const b = JSON.parse(input.aiNumericJSON);
const naiveEqual = a.invoice_id === b.invoice_id;
return [{json:{...input,naiveStatus:naiveEqual ? 'PASSED' : 'FAILED',naiveEqual,approvedParsed:String(a.invoice_id),aiParsed:String(b.invoice_id),unsafeNumeric:!Number.isSafeInteger(a.invoice_id)||!Number.isSafeInteger(b.invoice_id)}}];

const input = $input.first().json;
const parsedA = JSON.parse(input.approvedNumericJSON);
const parsedB = JSON.parse(input.aiNumericJSON);
// This is a demonstration of a safe verification boundary, not an Audital npm integration.
// Once digits are lost, no verifier can reconstruct the original value.
const unsafe = !Number.isSafeInteger(parsedA.invoice_id) || !Number.isSafeInteger(parsedB.invoice_id);
const numericStatus = unsafe ? 'INDETERMINATE' : (parsedA.invoice_id===parsedB.invoice_id?'PASSED':'FAILED');
// If we retained original exact string IDs, comparing them produces a definite answer.
const stringA=JSON.parse(input.approvedStringJSON);
const stringB=JSON.parse(input.aiStringJSON);
const losslessStatus = stringA.invoice_id === stringB.invoice_id ? 'PASSED' : 'FAILED';
return [{json:{case:input.case,naiveStatus:input.naiveStatus,naiveEqual:input.naiveEqual,approvedParsed:input.approvedParsed,aiParsed:input.aiParsed,numericStatus,losslessStatus,scope:'Synthetic invoice identifier only',why:'Standard JSON number parsing rounded distinct integers into the same unsafe JavaScript Number. Exact string IDs remain different.',disclaimer:'n8n Code-node demo, not an Audital production integration or live customer incident.'}}];
